import React from "react";

function AlertBox({ message, type, onClose }) {
  return (
    <div
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        background: "rgba(0,0,0,0.4)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        zIndex: 9999
      }}
    >
      <div
        style={{
          background: "#fff",
          padding: "25px",
          borderRadius: "12px",
          width: "320px",
          textAlign: "center",
          boxShadow: "0 10px 30px rgba(0,0,0,0.2)"
        }}
      >
        <h3
          style={{
            color: type === "success" ? "green" : "red",
            marginBottom: "10px"
          }}
        >
          {type === "success" ? "Success" : "Error"}
        </h3>

        <p>{message}</p>

        <button
          onClick={onClose}
          style={{
            marginTop: "15px",
            background: "#7b1fa2",
            color: "#fff",
            border: "none",
            padding: "10px 20px",
            borderRadius: "8px",
            cursor: "pointer"
          }}
        >
          OK
        </button>
      </div>
    </div>
  );
}

export default AlertBox;
